def k(x, n=2):
    return f"{x:.{n}f}".replace(".", ",")


def eur(x):
    s = f"€{x:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return s[:-3] if s.endswith(",00") else s


# ---- rekenvoorbeeld 1 (fictief): kennelijk foute odd van 15,00 waar de markt 1,50 geeft ----
INZET, FOUT, JUIST = 20, 15.00, 1.50
MET_FOUT = INZET * FOUT              # wat je had gekregen als de fout bleef staan
ONGELDIG = INZET * 1.00              # ongeldig: inzet terug
HERREKEND = INZET * JUIST            # herberekend tegen de juiste odd (alleen als je selectie wint)
assert (MET_FOUT, ONGELDIG, HERREKEND) == (300, 20, 30)

# ---- rekenvoorbeeld 2 (fictief): combi van drie, één selectie ongeldig ----
COMBI_INZET, BENEN = 10, (1.80, 2.10, 1.65)
COMBI_VOL = COMBI_INZET * BENEN[0] * BENEN[1] * BENEN[2]
COMBI_ZONDER = COMBI_INZET * BENEN[0] * BENEN[2]
assert (round(COMBI_VOL, 2), round(COMBI_ZONDER, 2)) == (62.37, 29.70)
assert round(BENEN[0] * BENEN[1] * BENEN[2], 2) == 6.24 and round(BENEN[0] * BENEN[2], 2) == 2.97

# ---- rekenvoorbeeld 3 (fictief): dead heat, inzet gedeeld door het aantal gedeelde winnaars ----
DH_INZET, DH_ODD = 10, 6.00
DH = {n: DH_INZET / n * DH_ODD for n in (1, 2, 3)}
assert DH == {1: 60, 2: 30, 3: 20}
DH_LAAG = DH_INZET / 2 * 1.50        # lage odd gedeeld door twee: minder terug dan je inzet
assert DH_LAAG == 7.5 and DH_LAAG < DH_INZET

content = f"""<p><strong>Een bookmaker mag je weddenschap alleen annuleren in situaties die in zijn voorwaarden staan. De belangrijkste zijn een kennelijke fout in de odds of de lijn, een weddenschap die per ongeluk is geaccepteerd nadat de wedstrijd begon of de uitslag al bekend was, en een technische storing. Meestal krijg je dan je inzet terug, omdat de weddenschap telt als odd 1,00. Sommige bookmakers rekenen in plaats daarvan af tegen de juiste odd. Ben je het er niet mee eens, dan dien je eerst een klacht in. Een legale bookmaker moet binnen acht weken schriftelijk reageren.</strong></p>
<p>Een geannuleerde weddenschap voelt als oneerlijk, zeker als je had gewonnen. Toch is het niet altijd willekeur. In dit artikel lees je wanneer een bookmaker mag ingrijpen, wat er dan met je geld gebeurt, wat TOTO, Unibet en bet365 daarover in hun voorwaarden zetten en welke stappen je in Nederland kunt zetten.</p>
<h3><strong>Wat is een kennelijke fout in de odds?</strong></h3>
<p>Een kennelijke fout (in het Engels <em>palpable error</em> of <em>obvious error</em>) is een vergissing die zo groot is dat iedereen kan zien dat het niet klopt. Denk aan een typefout of een storing in de datafeed waardoor een odd verkeerd op de site komt. Een paar voorbeelden:</p>
<ul><li><strong>Een komma op de verkeerde plek:</strong> 15,00 in plaats van 1,50 op een duidelijke favoriet.</li><li><strong>Een omgedraaide handicap:</strong> een team krijgt +1,5 terwijl het -1,5 had moeten zijn.</li><li><strong>Verwisselde teams:</strong> de odds van de thuisploeg staan bij de uitploeg.</li><li><strong>Een verkeerde lijn:</strong> over 0,5 doelpunten tegen een odd die bij over 3,5 hoort.</li></ul>
<p>Bookmakers toetsen dat meestal aan de rest van de markt. Wijkt een odd wezenlijk af van wat andere aanbieders op dat moment boden, of van de echte kans op de uitkomst, dan noemen ze het een fout. Een odd die net iets hoger is dan elders is géén fout. Dat is gewoon een scherpe prijs, en precies daar zoek je naar als je odds vergelijkt. Hoe je odds leest en omrekent naar een kans, lees je in <a href="{ODDS}">odds uitgelegd</a>.</p>
<h3><strong>Wanneer mag een bookmaker je weddenschap nog meer annuleren?</strong></h3>
<p>Naast een foute odd noemen de voorwaarden van Nederlandse bookmakers vooral deze situaties:</p>
<ul><li><strong>Late weddenschap:</strong> je weddenschap op een wedstrijd vóór de aftrap is geaccepteerd terwijl de wedstrijd al bezig was, of een live weddenschap terwijl de uitslag al vaststond.</li><li><strong>Vertraagde live-gegevens:</strong> de odds liepen achter op de echte stand, bijvoorbeeld omdat een doelpunt nog niet was verwerkt.</li><li><strong>Technische storing:</strong> een weddenschap die normaal niet geaccepteerd was, kwam door een systeemfout toch door.</li><li><strong>Verkeerde markt of deelnemer:</strong> er stond een speler of team bij de wedstrijd die niet meedoet.</li><li><strong>Nieuws dat de kansen verandert:</strong> een publieke aankondiging, zoals een afmelding, terwijl de odd nog niet was aangepast.</li><li><strong>Fraude of misbruik:</strong> matchfixing, wedden op een wedstrijd waarbij je zelf betrokken bent, of meerdere accounts.</li></ul>
<p>Een gestaakte of afgelaste wedstrijd valt onder aparte regels. Die lees je in ons artikel over <a href="{GESTAAKT}">een gestaakte wedstrijd</a>.</p>"""

